				biome,
				stratum: "Ore Vein",
				material: "Copper Ore",
				oreKey: "copper"
			};
			if (oreKind > -.35) return {
				biome,
				stratum: "Ore Vein",
				material: "Quartz Silicon",
				oreKey: "silicon"
