			bodyId: "planet",
			chunkX: 0,
			chunkY: 0,
			tx: 0,
			ty: 0,
			localX: 0,
			localY: 0,
			biome: "Regolith Plains",
			stratum: "Surface Crust",
			targetMaterial: "Surface Regolith",
			preloadedChunks: 9,
			minedCount: 0,
			lastMinedTile: "None",
			inventory: {
				iron: 0,
				copper: 0,
				titanium: 0,
				silicon: 0,
				ice: 0,
				stone: 0
			}
		};
