				let lastMinedTile = typeof prev.lastMinedTile === "string" ? prev.lastMinedTile : "None";
				const prevInv = typeof prev.inventory === "object" && prev.inventory !== null && !Array.isArray(prev.inventory) ? prev.inventory : initialRuleValue.inventory;
				let iron = Number(prevInv.iron ?? 0);
				let copper = Number(prevInv.copper ?? 0);
				let titanium = Number(prevInv.titanium ?? 0);
				let silicon = Number(prevInv.silicon ?? 0);
				let ice = Number(prevInv.ice ?? 0);
				let stone = Number(prevInv.stone ?? 0);
				const isLandedOrContact = primaryShip.state.status === "landed" || events.some((e) => "shipId" in e && e.shipId === primaryShip.id);
				const drillIntervalTicks = Math.max(10, Math.round(6e3 / Math.max(20, drillPower)));
				if (isLandedOrContact && tick > 0 && tick % drillIntervalTicks === 0) {
					minedCount += 1;
					lastMinedTile = sample.material;
					if (sample.oreKey === "iron") iron += 1;
					else if (sample.oreKey === "copper") copper += 1;
					else if (sample.oreKey === "titanium") titanium += 1;
					else if (sample.oreKey === "silicon") silicon += 1;
					else if (sample.oreKey === "ice") ice += 1;
					else stone += 1;
				}
				return { state: {
					version: 1,
					value: {
						bodyId: primaryShip.bodyId,
						chunkX,
						chunkY,
						tx,
						ty,
						localX,
						localY,
						biome: sample.biome,
						stratum: sample.stratum,
						targetMaterial: sample.material,
						preloadedChunks,
						minedCount,
						lastMinedTile,
						inventory: {
							iron,
							copper,
							titanium,
							silicon,
							ice,
							stone
						}
					}
				} };
			}
		});
	}
	//#endregion
	//#region games/space-sim-nextgen/portable-modules/planet-tiles-sim/src/entry.ts
	function entry(context) {
		initialize({
			...context,
			assets: { ...context.assets }
		});
	}
	//#endregion
	exports.default = entry;
	return exports;
})({});

