					const py0 = bodyOrigin.y + pcy * CHUNK_METRES;
					primitives.push({
						kind: "line",
						space: "world",
						closed: true,
						width: 1.2,
						color: "#22d3ee88",
						points: [
							{
								x: px0,
								y: py0
							},
							{
								x: px0 + CHUNK_METRES,
								y: py0
							},
							{
								x: px0 + CHUNK_METRES,
								y: py0 + CHUNK_METRES
							},
							{
								x: px0,
								y: py0 + CHUNK_METRES
