					const vectorLen = 8;
					primitives.push({
						kind: "line",
						space: "world",
						width: 2,
						color: "#4ade80cc",
						points: [shipWorld, {
							x: shipWorld.x + ux * vectorLen,
							y: shipWorld.y + uy * vectorLen
