					});
					primitives.push({
						kind: "line",
						space: "world",
						width: 1.5,
						color: "#38bdf8bb",
						points: [shipWorld, {
							x: shipWorld.x + tx * vectorLen,
							y: shipWorld.y + ty * vectorLen
