						const tileY0 = bodyOrigin.y + Math.floor(drillTargetY / TILE_METRES) * TILE_METRES;
						primitives.push({
							kind: "line",
							space: "world",
							width: ship.state.status === "landed" ? 2.5 : 1.2,
							color: ship.state.status === "landed" ? "#ff5522dd" : "#fbbf2488",
							points: [shipWorld, {
								x: tileX0 + TILE_METRES * .5,
								y: tileY0 + TILE_METRES * .5
