						primitives.push({
							kind: "line",
							space: "world",
							closed: true,
							width: 1.8,
							color: "#ff5522ee",
							points: [
								{
									x: tileX0,
									y: tileY0
								},
								{
									x: tileX0 + TILE_METRES,
									y: tileY0
								},
								{
									x: tileX0 + TILE_METRES,
									y: tileY0 + TILE_METRES
