				const rel = ship.state.position;
				const tx = typeof rule?.tx === "number" ? rule.tx : Math.floor(rel.x / TILE_METRES);
				const ty = typeof rule?.ty === "number" ? rule.ty : Math.floor(rel.y / TILE_METRES);
				const cx = typeof rule?.chunkX === "number" ? rule.chunkX : Math.floor(tx / 32);
				const cy = typeof rule?.chunkY === "number" ? rule.chunkY : Math.floor(ty / 32);
				const biome = typeof rule?.biome === "string" ? rule.biome : "Scanning...";
				const stratum = typeof rule?.stratum === "string" ? rule.stratum : "Crust";
				const targetMat = typeof rule?.targetMaterial === "string" ? rule.targetMaterial : "Regolith";
				const preloaded = typeof rule?.preloadedChunks === "number" ? rule.preloadedChunks : 9;
				const minedCount = typeof rule?.minedCount === "number" ? rule.minedCount : 0;
				const inv = typeof rule?.inventory === "object" && rule.inventory !== null && !Array.isArray(rule.inventory) ? rule.inventory : {};
