				const copper = Number(inv.copper ?? 0);
				const titanium = Number(inv.titanium ?? 0);
				const silicon = Number(inv.silicon ?? 0);
				const ice = Number(inv.ice ?? 0);
				const horizonDeg = hypot(rel.x, rel.y) > 1e-6 ? (atan2(rel.y, rel.x) * 180 / Math.PI).toFixed(1) : "0.0";
				return [
					{
						label: "Active Planet",
						value: `${view.body.name} (R=${Math.round(view.body.radius)}m)`
					},
					{
						label: "Chunk (Cx, Cy)",
						value: `(${cx}, ${cy})`,
						unit: "16m"
					},
					{
						label: "Tile (Tx, Ty)",
						value: `(${tx}, ${ty})`,
						unit: "0.5m"
					},
					{
						label: "Polar Angle",
						value: horizonDeg,
						unit: "deg"
					},
					{
						label: "Surface Biome",
						value: biome
					},
					{
						label: "Subsurface",
						value: stratum
					},
					{
						label: "Drill Reticle",
						value: targetMat
					},
					{
						label: "Stream Queue",
						value: `${preloaded} chunks`,
						unit: "LRU"
					},
					{
						label: "Excavated",
						value: `${minedCount} tiles`
					},
					{
						label: "Fe / Cu / Si",
						value: `${iron} / ${copper} / ${silicon}`
					},
					{
						label: "Ti / Ice",
						value: `${titanium} / ${ice}`
					}
				];
			}
		});
		context.contributeCamera({
			name: "horizon-eva",
			label: "Horizon EVA camera",
			frame(input) {
				const ship = input.ship;
				if (!ship) return {
					center: input.body.position,
					rotation: 0
				};
				const rel = ship.state.position;
				const angle = rel.x === 0 && rel.y === 0 ? 0 : normalizeAngle(atan2(rel.y, rel.x) - Math.PI * .5);
				return {
					center: ship.position,
					rotation: -angle
				};
			}
		});
	}
	//#endregion
	//#region games/space-sim-nextgen/portable-modules/planet-tiles-hud/src/entry.ts
	function entry(context) {
		initialize({
			...context,
			assets: { ...context.assets }
		});
	}
	//#endregion
	exports.default = entry;
	return exports;
